import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BywSET8q.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),i={name:"docs/index.md"};function n(s,e,d,l,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Auth is hard. OAuth can be even harder—both to understand and to implement. The goal of the Okta Client JavaScript ecosystem is to enable developers to seamlessly integrate OAuth2 (and Okta APIs) into the applications they author, regardless of environment, and without requiring a comprehensive understanding of all the intricacies of the OAuth2 spec.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><p>At Okta, we strive for architectural parity across all of our client SDKs, regardless of language or environment. See the <a href="https://okta-client-design.netlify.app/design/" target="_blank" rel="noreferrer">Okta SDK Design</a> site for more details.</p><p>Okta Client JavaScript is developed with a developer-first approach. Our goal is to enable developers to seamlessly incorporate OAuth2 into new and (perhaps more importantly) existing applications without requiring major refactoring. We carefully consider how a developer would use any new class (pun fully intended), API, or paradigm before committing to the approach and merging it into the ecosystem.</p>',6)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
